#include "stdafx.h"#include "Server.h"#include <io.h>#include <CommonRSUs.h>int KServer::StateSave( LPCSTR pszPath ){  DeleteFile( pszPath );  char drive[_MAX_DRIVE];  char dir[_MAX_DIR];  char fname[_MAX_FNAME];  char ext[_MAX_EXT];  char path_tmp[_MAX_PATH] = { 0 };  char filenameinzip[_MAX_FNAME] = { 0 };  _splitpath_s( pszPath, drive, _countof(drive), dir, _countof(dir), fname, _countof(fname), ext, _countof(ext) );  _makepath_s( filenameinzip, NULL, NULL, fname, ext );  strcpy_s( path_tmp, pszPath );  strcat_s( path_tmp, ".tmp" );  int res = StateSaveL( path_tmp );  RsuPackager( path_tmp, pszPath, filenameinzip );  DeleteFile( path_tmp );  return res;}int KServer::StateRestore( LPCSTR pszPath ){  if( 0!=_access( pszPath, 0) )    return 1;  HANDLE hRest = RsuExtractor( pszPath );  int res = StateRestoreL( hRest );  return 0;}